private lemma criticalExponent_mem_aux :
    criticalExponent ∈ Icc 2 3 ∧
      criticalExponent ^ 3 - 2 * criticalExponent ^ 2 - 2 * criticalExponent + 2 = 0

theorem lintegral_mul_le_plateMaximal {n k : ℕ} {δ : ℝ} (hδ : 0 < δ)
    (V : Grassmannian n k) {f K : EuclideanSpace ℝ (Fin n) → ℝ≥0∞}
    (hf : Measurable f) (hK : Measurable K) {C : ℝ≥0}
    (hshift : ∀ z t, t ∈ plate δ V.val 0 → K z ≤ C * K (z - t)) :
    (∫⁻ z, f z * K z) ≤ C * plateMaximal δ f V * ∫⁻ z, K z

theorem lintegral_mul_le_of_translated_averages {f K : G → ℝ≥0∞}
    (hf : Measurable f) (hK : Measurable K) {S : Set G} (hS : MeasurableSet S)
    (hS₀ : μ S ≠ 0) (hSfin : μ S ≠ ∞) {C : ℝ≥0} {M : ℝ≥0∞}
    (hshift : ∀ z t, t ∈ S → K z ≤ C * K (z - t))
    (havg : ∀ z, (∫⁻ t in S, f (z + t) ∂μ) ≤ M * μ S) :
    (∫⁻ z, f z * K z ∂μ) ≤ C * M * ∫⁻ z, K z ∂μ

theorem isOpen_setOf_mem_plate_rotate (δ : ℝ) (a x : EuclideanSpace ℝ (Fin n))
    (V : Grassmannian n k) :
    IsOpen {u : Rotations n | x ∈ plate δ (Grassmannian.rotate u V).val a}

private theorem exists_larger_radius_aux {s : ℝ} (hs : 0 < s) {d : ℝ≥0} (hd : d < 1)
    {ε : ℝ≥0∞} (hε : 0 < ε) :
    ∃ r : ℝ≥0, d < r ∧ r < 1 ∧ (r : ℝ≥0∞) ^ s < (d : ℝ≥0∞) ^ s + ε

theorem hausdorffMeasure_ne_zero_of_plateEstimate {n k : ℕ} {hkn : k ≤ n} {α p s : ℝ}
    (hp : 1 ≤ p) (hs : 0 < s) (hgap : s < (n : ℝ) - α)
    (h : Induction.HasPlateEstimate hkn α p) {E : Set (EuclideanSpace ℝ (Fin n))}
    (hB : IsBesicovitch k E) : μH[s] E ≠ 0

theorem HasPlateEstimate.le_dimH {n k : ℕ} {hkn : k ≤ n} {α p : ℝ} (hp : 1 ≤ p)
    (h : HasPlateEstimate hkn α p) {E : Set (EuclideanSpace ℝ (Fin n))}
    (hB : IsBesicovitch k E) : ENNReal.ofReal ((n : ℝ) - α) ≤ dimH E

theorem volume_pos_of_isBesicovitch_self {E : Set (EuclideanSpace ℝ (Fin n))}
    (hE : IsBesicovitch n E) :
    0 < volume E

theorem measurableSet_normalSlopes [MeasurableSpace E] [BorelSpace E]
    {v : E} (hv : ‖v‖ = 1) (c : ℝ) :
    MeasurableSet {ξ : (ℝ ∙ v)ᗮ | c ≤ ⟪v, (normalDirection hv ξ : E)⟫_ℝ}

private theorem xray_ratio_parameters {Q β ρ : ℝ} (hQ : 0 < Q) (hβ : 1 < β)
    (hβ2 : β ≤ 2) (hlo : 1 < ρ * (β - 1)) (hhi : ρ * (β - 1) < β) :
    let p := Q / (ρ * (β - 1))
    0 < p ∧ Q / β < p ∧ p ≤ Q ∧ Q ≤ ρ * p ∧ ρ * p = Q / (β - 1)

theorem exists_ratio_lt_criticalExponent {n k : ℕ}
    (h : (n : ℝ) < criticalExponent ^ (k - 1) + (k : ℝ)) :
    ∃ ρ ∈ Ioo 2 criticalExponent, (n : ℝ) < ρ ^ (k - 1) + (k : ℝ)

private theorem plate_coefficient_power (C δ : ℝ≥0) {α a ρ p t : ℝ}
    (ha : 0 < a) (hρ : 0 < ρ) (hp : 0 < p) (ht : t = ρ * p / a) :
    (C * δ ^ (-α / a)) ^ t⁻¹ = C ^ t⁻¹ * δ ^ (-(α / ρ) / p)

theorem lintegral_le_mul_measure_of_ae_le {X : Type*} [MeasurableSpace X] {μ : Measure X}
    {f : X → ℝ≥0∞} {S : Set X} (hS : Function.support f ⊆ S) {C : ℝ≥0∞}
    (hC : ∀ᵐ x ∂μ, f x ≤ C) : (∫⁻ x, f x ∂μ) ≤ C * μ S

theorem sq_volume_le_projection_mul_pairMass (a : ℝ) {G : Set (Line m)}
    (hG : MeasurableSet G) :
    volume G ^ 2 ≤ volume (atHeight a '' G) * volume (pairFamily a G)

