theorem corner_exponent_main_term {β : ℝ} (hβ : 1 < β) :
    let q := β / (β - 1)
    (2 * q + 3 * q ^ 2 - 2) / (q + 2 * q ^ 2 - 2) = cornerUpdate β

theorem volume_parallelFiber_smul {r : ℝ} (hr : 0 < r) (G : Set (Line m))
    (ξ : EuclideanSpace ℝ (Fin m)) :
    volume {x | (x, ξ) ∈ r • G} = ENNReal.ofReal (r ^ m) * volume {x | (x, r⁻¹ • ξ) ∈ G}

theorem le_pairDensity_of_mem_sdiff_lowPairs {a s t : ℝ}
    {W : Set (PairCoordinates m)} {Q : ℝ≥0∞} {p : PairCoordinates m}
    (hp : p ∈ W \ lowPairs a s t W Q) :
    Q ≤ pairDensity a s t W (pairProjections a s t p)

theorem lowPairs_eq_of_density_bound (a s t : ℝ) {W : Set (PairCoordinates m)}
    {Q : ℝ≥0∞} (hQ : ∀ p ∈ W, pairDensity a s t W (pairProjections a s t p) < Q) :
    lowPairs a s t W Q = W

theorem lowPairs_eq_of_projection_bound (a s t : ℝ) {G : Set (Line m)}
    {W : Set (PairCoordinates m)} (hWG : W ⊆ pairFamily a G) {Q : ℝ≥0∞}
    (hQ : pairJacobian m a s t * volume (atHeight a '' G) < Q) :
    lowPairs a s t W Q = W

theorem measurable_codeSliceMass (a b c : ℝ) {W : Set (PairCoordinates m)}
    (hW : MeasurableSet W) (z : EuclideanSpace ℝ (Fin m)) : Measurable
      (codeSliceMass a b c W z)

theorem codeDensity_bounds_of_mem_retainedCodePairs {a b : ℝ} {c : ι → ℝ} {I : Finset ι}
    {W E : Set (PairCoordinates m)} {p : PairCoordinates m}
    (hp : p ∈ retainedCodePairs a b c I W E) {i : ι} (hi : i ∈ I) :
    0 < codeDensity a b (c i) W (pairCode a b (c i) p) ∧
      codeDensity a b (c i) W (pairCode a b (c i) p) ≤
