theorem times_subset (T : CornerTree m β J) {I : Set ℝ}
    (ha : ∀ v, T.a v ∈ I) (hb : ∀ v, T.b v ∈ I) (hc : ∀ v, T.c v ∈ I)
    (hP : ∀ v h, ∀ t ∈ (T.pattern v h).times, t ∈ I) : ∀ t ∈ T.times, t ∈ I

theorem innerCorners_eq_inter {a b : ℝ} {W : Set (PairCoordinates m)}
    {G₀ A B : Set (Line m)} (hW : W ⊆ companionPairs b G₀ B) :
    innerCorners a b A W = companionCorners a b G₀ A B ∩ cornerInner b ⁻¹' W

theorem HasProjectionEstimate.translate {β : ℝ} {Γ : Finset ℝ}
    (h : HasProjectionEstimate m β Γ) (a : ℝ) :
    HasProjectionEstimate m β (Γ.image (· + a))

theorem cornerThreshold_budget (v : ℝ≥0∞) {N R : ℝ≥0∞}
    (hN₀ : N ≠ 0) (hN : N ≠ ∞) (hR₀ : R ≠ 0) (hR : R ≠ ∞) {r : ℕ} (hr : r ≠ 0) :
    r * cornerThreshold v N R r * N * R = v / 2

theorem cornerFiber_mono (a b c κ : ℝ) {D₀ D₁ : Set (CornerCoordinates m)}
    (hD : D₁ ⊆ D₀) (z : EuclideanSpace ℝ (Fin m)) :
    cornerFiber a b c κ D₁ z ⊆ cornerFiber a b c κ D₀ z

theorem continuous_volume_inter_closedBall [Nonempty (Fin m)] {S : Set (EuclideanSpace ℝ (Fin m))}
    (hS : MeasurableSet S) (hfin : volume S ≠ ∞) :
    Continuous (fun r : ℝ ↦ volume (S ∩ closedBall 0 r))

theorem sliceBallMass_one (a R : ℝ) {G : Set (Line m)}
    (hR : ∀ g ∈ G, ‖g.2‖ ≤ R) (y : EuclideanSpace ℝ (Fin m)) :
    sliceBallMass a G R y 1 = sliceMultiplicity a G y

theorem le_cornerOuterDensity_of_mem_denseCorners {a b c κ : ℝ} {u : ι → ℝ} {I : Finset ι}
    {D : Set (CornerCoordinates m)} {τ : ℝ≥0∞} {p : CornerCoordinates m}
    (hp : p ∈ denseCorners a b c κ u I D τ) {i : ι} (hi : i ∈ I) :
