theorem parentCorners_eq_inter {a b : ℝ} {U : Set (PairCoordinates m)}
    {G₀ A B : Set (Line m)} (hU : U ⊆ companionPairs a G₀ A) :
    parentCorners a b U B = companionCorners a b G₀ A B ∩ cornerParent a ⁻¹' U

theorem parentCorners_sdiff_inner_preimage_subset {a b : ℝ}
    {G₀ A B : Set (Line m)} {U W : Set (PairCoordinates m)}
